?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>SEO Quality Gates | TechSelectAI</title><style>body{font-family:system-ui;margin:0;background:#f6f8fb;color:#1f2937}.wrap{max-width:1250px;margin:auto;padding:24px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:18px 0}.card,.panel{background:#fff;border:1px solid #dde5ee;border-radius:14px;padding:16px}.kpi{font-size:28px;font-weight:800}.muted{color:#64748b;font-size:13px}button{padding:9px 13px;border-radius:9px;border:1px solid #cdd7e1;background:#fff;cursor:pointer}.primary{background:#173b63;color:#fff}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:9px;border-bottom:1px solid #edf2f7;text-align:left;vertical-align:top}.bad{color:#9b1c1c}.warn{color:#8a5b00}.ok{color:#17603a}@media(max-width:700px){.cards{grid-template-columns:1fr 1fr}}</style></head><body><div class="wrap"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap"><div><h1>Programmatic SEO Quality Gates</h1><div class="muted">Only published pages with an explicit <b>indexable</b> decision may enter the sitemap.</div></div><button class="primary" id="runAll">Run all gates</button></div><div class="cards"><div class="card"><div class="muted">Total</div><div class="kpi" id="total">0</div></div><div class="card"><div class="muted">Indexable</div><div class="kpi" id="indexable">0</div></div><div class="card"><div class="muted">Noindex</div><div class="kpi" id="noindex">0</div></div><div class="card"><div class="muted">Blocked</div><div class="kpi" id="blocked">0</div></div></div><div class="panel"><div id="settings" class="muted"></div><div class="tablewrap"><table><thead><tr><th>Page</th><th>Type</th><th>Decision</th><th>Score</th><th>Reasons</th><th>Canonical</th><th></th></tr></thead><tbody id="rows"></tbody></table></div></div></div><script>let csrf='';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function load(){const r=await fetch('/api/seo-quality-gates',{credentials:'same-origin'}),j=await r.json();if(!r.ok){alert(j.error||'Load failed');return;}csrf=j.csrf_token;for(const k of ['total','indexable','noindex','blocked'])document.getElementById(k).textContent=j.summary?.[k]||0;settings.textContent='Thresholds: '+Object.entries(j.settings||{}).map(([k,v])=>k+'='+v).join(' · ');rows.innerHTML=(j.pages||[]).map(p=>`<tr><td><b>${esc(p.title)}</b><br><span class="muted">${esc(p.canonical_path)}</span></td><td>${esc(p.page_type)}</td><td class="${p.quality_decision==='indexable'?'ok':p.quality_decision==='not_generated'?'bad':'warn'}">${esc(p.quality_decision)}</td><td>${esc(p.quality_score??'—')}</td><td>${(p.reasons||[]).map(esc).join('<br>')||'—'}</td><td>${esc(p.canonical_target_path||'—')}</td><td><button onclick="runOne(${p.id})">Re-run</button></td></tr>`).join('');}async function runOne(id){await fetch('/api/seo-quality-gates/'+id+'/run',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':csrf}});load();}runAll.onclick=async()=>{runAll.disabled=true;await fetch('/api/seo-quality-gates/run-all',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':csrf}});runAll.disabled=false;load();};load();</script></body></html>